/*
 * Ported from LAMMPS (https://github.com/lammps/lammps, commit b332f28): the first check of the constructor of each fix
 * and compute style (src/fix_*.cpp, src/compute_*.cpp and the package directories) when that check is on the number of
 * words of the command (narg: the ID, the group, the style and its arguments), and the first check of the settings()
 * of each pair style on its number of words, with native's messages; and the style names of every package by kind (the
 * XStyle(name, Class) registrations of the headers), which utils::check_packages_for_style looks a name up in. LAMMPS is
 * Copyright Sandia Corporation and distributed under the GNU General Public License, version 2 (GPL-2.0); this file is
 * GPL-2.0 too (src/engine-gpl/LICENSE).
 *
 * Each entry is the style, the kind of test (min: narg below the first number is refused; only: narg must be one of the
 * numbers; range: narg between the two numbers) and native's message, with its error page number when it has one. The
 * styles whose constructor checks something else first are not listed: the engine's own constructor checks them.
 *
 * Registered for the core through src/engine/lazyStyles.ts (kind HOOKS, words 'fix', 'compute', 'pair_style' and
 * 'native_styles'): the fix and compute commands (src/engine/commands/run.ts) call gplHook('fix') and gplHook('compute')
 * before they make the style, pair_style (commands/forcefield.ts) gplHook('pair_style') before its settings, and
 * src/engine/nativeStyles.ts reads the style names through gplHook('native_styles').
 */
const errorUrl = (n: number): string => `\nFor more information see https://docs.lammps.org/err${String(n).padStart(4, '0')}`;

type ArgCheck = readonly [kind: 'min' | 'only' | 'range', nums: readonly number[], message: string, page: string];

