const SETS = new Map<string, ReadonlySet<string>>();
/** The accelerator suffixes a native style name may carry (OPENMP, GPU, KOKKOS, INTEL, OPT). */
const SUFFIX = /\/(omp|gpu|kk|kk\/device|kk\/host|intel|opt|lrt\/intel)$/;

/** Whether some LAMMPS package has a style of this kind and name (with or without an accelerator suffix). */
const knownStyle = (kind: string, name: string): boolean => {
  let set = SETS.get(kind);
  if (!set) {
    set = new Set((NATIVE_STYLES[kind] ?? '').split(' '));
    SETS.set(kind, set);
  }
  return set.has(name) || set.has(name.replace(SUFFIX, ''));
};

const nativeArgCheck = (what: 'fix' | 'compute' | 'pair_style', style: string, narg: number): string | null => {
  const table = what === 'fix' ? FIX_ARG_CHECKS : what === 'compute' ? COMPUTE_ARG_CHECKS : PAIR_SETTINGS_CHECKS;
  // an accelerated variant (lj/cut/omp, nve/kk) checks as its base style does
  const c = table[style] ?? table[style.replace(SUFFIX, '')];
  if (!c) return null;
  const [kind, nums, message, page] = c;
  const bad = kind === 'min' ? narg < nums[0] : kind === 'only' ? !nums.includes(narg) : narg < nums[0] || narg > nums[1];
  return bad ? `${message.replace('{narg}', String(narg))}${page ? errorUrl(Number(page)) : ''}` : null;
};

