/** The charge requirement of a pair style's init_style (accelerator suffixes stripped), or null. */
const pairQText = (style: string): string | null => PAIR_Q_TEXT[style.replace(SUFFIX, '')] ?? null;

export const HOOKS = {
  fix: (style: string, narg: number): string | null => nativeArgCheck('fix', style, narg),
  compute: (style: string, narg: number): string | null => nativeArgCheck('compute', style, narg),
  /** pair_style: narg is the number of words after the style name (Pair::settings) */
  pair_style: (style: string, narg: number): string | null => nativeArgCheck('pair_style', style, narg),
  /** the init_one message for an unset I,J pair, read by the pair styles' init (StyleContext.pairUnsetText) */
  pair_unset: pairUnsetText,
  /** the charge requirement of a pair style's init_style (StyleContext.pairNeedsQ) */
  pair_q: pairQText,
  native_styles: { known: knownStyle },
  /** the same names, stored under atom_style so that the command loads them before it reads its sub-styles */
  atom_style: { known: knownStyle },
};
